def _should_execute_hook(self, hook_type, tid, is_forward=True):
    is_api_hook = hook_type == Const.API
    is_dynamic_enable_mode = getattr(self.config, "dump_enable", None) is not None
    if is_dynamic_enable_mode:
        if is_api_hook and self.config.level not in [Const.LEVEL_MIX, Const.LEVEL_L1, Const.LEVEL_L2]:
            return False
        if hook_type == Const.MODULE and self.config.level not in [Const.LEVEL_MIX, Const.LEVEL_L0]:
            return False
    if self.is_child_process():
        return False
    if BaseHookManager.inner_switch[tid]:
        return False
    if not is_api_hook and not Runtime.is_running:
        return False
    elif is_api_hook and is_forward and not Runtime.is_running:
        return False
    if not self.data_collector or self.data_collector.data_processor.is_terminated:
        return False
    return True

def forward_output_data_collect(self, name, module, pid, module_input_output):
    self.update_construct(name)
    if not self.should_collect(name, pid):
        return

    data_info = {}
    if self.config.task != Const.STRUCTURE:
        data_info = self.data_processor.analyze_forward_output(name, module, module_input_output)
    if self.config.level == Const.LEVEL_L2:
        return
    self.handle_data(name, data_info, flush=self.data_processor.is_terminated)

def analyze_forward_output(self, name, module, module_input_output: ModuleForwardInputsOutputs):
    if self.is_distributed_op(module):
        module_input_output.update_output_with_args_and_kwargs()
    api_info_struct = {}
    # check whether data_mode contains forward or input
    if self.is_dump_for_data_mode(Const.FORWARD, Const.OUTPUT):
        api_info_struct[name] = {}
        self.api_data_category = Const.OUTPUT
        output_info_list = self.analyze_element(
            self._apply_ignore_rules(module_input_output.output_tuple, Const.FORWARD, Const.OUTPUT)
        )
        api_info_struct[name][Const.OUTPUT] = output_info_list

    return api_info_struct

def get_tensor_dtype(tensor):
    if is_hifloat8_tensor(tensor):
        return PtConst.HIFLOAT8_TYPE
    return str(tensor.dtype)

def convert_common_tensor(self, tensor):
    if self.is_dtensor(tensor):
        return tensor.to_local()
    if self.is_fake_tensor(tensor):
        logger.debug("FakeTensor cannot be converted to torch.Tensor type.")
        return tensor
    if self.is_nested_tensor(tensor):
        logger.debug("For NestedTensor, collecting information from the tensor returned by .values().")
        return tensor.values()
    for _ in range(Const.MAX_DEPTH):
        if self.is_batchedtensor(tensor):
            tensor = torch._C._functorch.get_unwrapped(tensor)
        else:
            return tensor
    return tensor

def _replace_stat_placeholders(self, data, stat_result):
    if isinstance(data, dict):
        keys = list(data.keys())  # 获取当前所有键
        for key in keys:  # 递归所有变量
            value = data[key]
            if key == Const.TENSOR_STAT_INDEX and isinstance(value, int):
                if value >= 0:
                    idx = value
                else:
                    return
                stat_values = stat_result[idx] if idx < len(stat_result) else [None] * 5
                check_sum = stat_values[4] if len(stat_values) > 4 else None
                summary_mode = getattr(getattr(self, "config", None), "summary_mode", None)

                new_entries = {
                    Const.TYPE: data["type"],
                    Const.DTYPE: data["dtype"],
                    Const.SHAPE: data["shape"],
                }
                if summary_mode == Const.XOR_CHECKSUM:
                    new_entries[Const.MD5] = check_sum
                else:
                    new_entries.update(
                        {
                            Const.MAX: stat_values[0],
                            Const.MIN: stat_values[1],
                            Const.MEAN: stat_values[2],
                            Const.NORM: stat_values[3],
                        }

def flush_stat_stack(self):
    """
    在 flush 阶段，将所有存储的统计值从设备搬到 CPU，
    这里返回一个列表，每个元素是 [Max, Min, Mean, Norm] 的数值列表
    """
    if not self.stat_stack_list:
        return []

    def _resolve_stat_value(x, pos):
        if isinstance(x, concurrent.futures.Future):
            try:
                x = x.result()
            except Exception as e:
                logger.warning(f"Failed to resolve async tensor stat value with error info: {e}.")
                return None
        x = x.item() if hasattr(x, "item") else x
        if pos == 4 and isinstance(x, int):
            return f"0x{(x & ((1 << 64) - 1)):016x}"
        return x

    result = [
        [_resolve_stat_value(x, i) for i, x in enumerate(stat_values)] for stat_values in self.stat_stack_list
    ]
    self.stat_stack_list = []
    return result
